def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []

    # Candidate 2x2 squares and 3-cell L tiles.
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                tiles.append((box, 1))
            for missing, color in [
                ((r, c), 2),          # missing upper-left
                ((r, c + 1), 4),      # missing upper-right
                ((r + 1, c), 3),      # missing lower-left
                ((r + 1, c + 1), 3),  # missing lower-right
            ]:
                piece = box - {missing}
                if piece <= cells:
                    tiles.append((piece, color))

    by_cell = {p: [] for p in cells}
    for piece, color in tiles:
        for p in piece:
            by_cell[p].append((piece, color))

    # Exact-cover the 8s into squares and Ls; prefer squares.
    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda q: sum(piece <= left for piece, _ in by_cell[q]))
        options = sorted((x for x in by_cell[p] if x[0] <= left),
                         key=lambda x: -len(x[0]))
        for piece, color in options:
            rest = solve(left - piece)
            if rest is not None:
                return [(piece, color)] + rest
        return None

    chosen = solve(cells)
    out = [[0] * w for _ in range(h)]
    if chosen:
        for piece, color in chosen:
            for r, c in piece:
                out[r][c] = color
    return out
